import { Marker, MarkerContent, MarkerIcon } from "@/registry/erbium/ui/marker";
import { Spinner } from "@/registry/erbium/ui/spinner";

export function MarkerStatusDemo() {
  return (
    <div className="flex w-full max-w-sm flex-col gap-8 py-12">
      <Marker role="status">
        <MarkerIcon>
          <Spinner />
        </MarkerIcon>
        <MarkerContent>Compacting conversation</MarkerContent>
      </Marker>
      <Marker variant="separator" role="status">
        <MarkerIcon>
          <Spinner />
        </MarkerIcon>
        <MarkerContent>Running tests</MarkerContent>
      </Marker>
    </div>
  );
}

import { MarkerStatusDemo } from "../examples/marker-status";

const Example = () => (
  <div className="w-72 max-w-[calc(100vw-2rem)]">
    <MarkerStatusDemo />
  </div>
);

export default Example;
